  // Sync and save integration configuration directly with Server and Supabase Cloud DB
  const saveIntegrationToServerAndSupabase = async (integrationObj: any) => {
    const settingsPayload = {
      apiKey: integrationObj.apiKey || '',
      publicKey: integrationObj.publicKey || '',
      endpointUrl: integrationObj.endpointUrl || '',
      environment: integrationObj.environment || 'live',
      status: integrationObj.status || 'configured',
      description: integrationObj.description || '',
      webhookSecret: integrationObj.webhookSecret || '',
      voiceId: integrationObj.voiceId || '',
      modelName: integrationObj.modelName || '',
      senderEmail: integrationObj.senderEmail || '',
      category: integrationObj.category || '',
      name: integrationObj.name || ''
    };

    // 1. Save directly to Server REST API
    try {
      await fetch('/api/admin/integrations/save', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          integrationId: integrationObj.id,
          settings: settingsPayload
        })
      });
    } catch (err) {
      console.warn('⚡ Server API integration save notice:', err);
    }

    // 2. Persist directly to Supabase cloud database if available
    if (heartsync.supabase) {
      try {
        await heartsync.supabase.from('integrations').upsert([{
          id: integrationObj.id,
          name: integrationObj.name,
          category: integrationObj.category || 'API Integration',
          description: integrationObj.description || '',
          is_enabled: integrationObj.status !== 'disabled',
          updated_at: new Date().toISOString()
        }]);

        for (const [key, value] of Object.entries(settingsPayload)) {
          if (value !== undefined && value !== null) {
            const isSensitive = key.toLowerCase().includes('key') || key.toLowerCase().includes('secret') || key.toLowerCase().includes('token');
            await heartsync.supabase.from('integration_settings').upsert([{
              id: `${integrationObj.id}_${key}`,
              integration_id: integrationObj.id,
              key: key,
              value: String(value),
              is_sensitive: isSensitive,
              updated_at: new Date().toISOString()
            }]);
          }
        }
      } catch (sbErr) {
        console.warn('⚡ Supabase direct integration upsert warning:', sbErr);
      }
    }
  };

// Remove here, moving below activePane declaration



  // Keyboard shortcut listener for Cmd+K / Ctrl+K and Escape
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault();
        setIsCommandPaletteOpen(prev => !prev);
      } else if (e.key === 'Escape' && isCommandPaletteOpen) {
        setIsCommandPaletteOpen(false);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isCommandPaletteOpen]);

  const handleExportBackup = () => {
    const fullBackup = {
      version: '2.0.0',
      exportedAt: new Date().toISOString(),
      posts: heartsync.posts,
      categories: heartsync.categories,
      site_settings: heartsync.site_settings,
      comments: heartsync.comments,
      subscribers: heartsync.subscribers,
      authors: heartsync.authors,
      pages: heartsync.pages,
      tags: heartsync.tags,
      podcasts: heartsync.podcasts,
      rss_feeds: heartsync.rss_feeds,
      audit_logs: heartsync.audit_logs
    };
    const blob = new Blob([JSON.stringify(fullBackup, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `heartsync-cms-backup-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
    triggerToast('Full site database backup exported as JSON!');
  };

  const handleImportBackup = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (data.posts && Array.isArray(data.posts)) {
          heartsync.posts = data.posts;
          if (data.categories) heartsync.categories = data.categories;
          if (data.site_settings) heartsync.site_settings = data.site_settings;
          if (data.comments) heartsync.comments = data.comments;
          if (data.subscribers) heartsync.subscribers = data.subscribers;
          if (data.authors) heartsync.authors = data.authors;
          if (data.pages) heartsync.pages = data.pages;
          if (data.tags) heartsync.tags = data.tags;
          if (data.podcasts) heartsync.podcasts = data.podcasts;
          if (data.rss_feeds) heartsync.rss_feeds = data.rss_feeds;
          heartsync.saveState();

          setPosts([...heartsync.posts]);
          setCategories([...heartsync.categories]);
          setSiteSettings({ ...heartsync.site_settings });
          setComments([...heartsync.comments]);
          setSubscribers([...heartsync.subscribers]);
          setMediaFiles([...heartsync.getMediaItems()]);
          setAnalytics(heartsync.getLiveAnalytics());
          setAuthors([...heartsync.authors]);
          setPages([...heartsync.pages]);
          triggerToast('Full database state imported & synchronized successfully!');
        } else {
          triggerToast('Invalid backup file structure.');
        }
      } catch (err) {
        triggerToast('Failed to parse backup JSON file.');
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

