  useEffect(() => {
    async function loadServerIntegrations() {
      try {
        const res = await fetch('/api/admin/integrations');
        if (res.ok) {
          const data = await res.json();
          if (data && data.settings && Array.isArray(data.settings)) {
            const settingsByInt: Record<string, Record<string, string>> = {};
            data.settings.forEach((s: any) => {
              if (s.integration_id && s.key) {
                if (!settingsByInt[s.integration_id]) settingsByInt[s.integration_id] = {};
                settingsByInt[s.integration_id][s.key] = s.value;
              }
            });

            setIntegrationsList(prev => {
              return prev.map(item => {
                const sMap = settingsByInt[item.id];
                if (!sMap) return item;
                return {
                  ...item,
                  apiKey: sMap.apiKey || sMap.secret_key || sMap.api_key || item.apiKey,
                  publicKey: sMap.publicKey || sMap.public_key || item.publicKey,
                  endpointUrl: sMap.endpointUrl || sMap.endpoint_url || item.endpointUrl,
                  environment: sMap.environment || item.environment,
                  status: sMap.status || item.status,
                  description: sMap.description || item.description,
                  webhookSecret: sMap.webhookSecret || item.webhookSecret,
                  updatedAt: new Date().toISOString().split('T')[0]
                };
              });
            });
          }
        }
      } catch (err) {
        console.warn('⚡ Server integrations fetch notice:', err);
      }

      if (heartsync.supabase) {
        try {
          const { data: sbSettings } = await heartsync.supabase.from('integration_settings').select('*');
          if (sbSettings && sbSettings.length > 0) {
            const sbMap: Record<string, Record<string, string>> = {};
            sbSettings.forEach((s: any) => {
              if (s.integration_id && s.key) {
                if (!sbMap[s.integration_id]) sbMap[s.integration_id] = {};
                sbMap[s.integration_id][s.key] = s.value;
              }
            });

            setIntegrationsList(prev => {
              return prev.map(item => {
                const sMap = sbMap[item.id];
                if (!sMap) return item;
                return {
                  ...item,
                  apiKey: sMap.apiKey || sMap.secret_key || sMap.api_key || item.apiKey,
                  publicKey: sMap.publicKey || sMap.public_key || item.publicKey,
                  endpointUrl: sMap.endpointUrl || sMap.endpoint_url || item.endpointUrl,
                  environment: sMap.environment || item.environment,
                  status: sMap.status || item.status,
                  description: sMap.description || item.description,
                  webhookSecret: sMap.webhookSecret || item.webhookSecret,
                  updatedAt: new Date().toISOString().split('T')[0]
                };
              });
            });
          }
        } catch (sbErr) {
          console.warn('⚡ Supabase integration settings warning:', sbErr);
        }
      }
    }

    if (activePane === 'integrations') {
      loadServerIntegrations();
    }
  }, [activePane]);

