  const fetchDbUsers = async () => {
    if (!heartsync.supabase) return;
    setDbUsersLoading(true);
    try {
      const { data: profiles, error: err } = await heartsync.supabase
        .from('profiles')
        .select('*')
        .order('created_at', { ascending: false });
      
      if (err) {
        console.error('Error fetching db profiles:', err);
      } else if (profiles) {
        setDbUsers(profiles);
      }
    } catch (e) {
      console.error('Error fetching db profiles:', e);
    } finally {
      setDbUsersLoading(false);
    }
  };

  const handleUpdateUserRole = async (userId: string, userEmail: string, newRole: string) => {
    if (!heartsync.supabase) return;
    try {
      const cleanEmail = userEmail.toLowerCase().trim();
      const cleanRole = newRole.toLowerCase();

      // 1. Update profiles table
      const { error: profileErr } = await heartsync.supabase
        .from('profiles')
        .update({ role: cleanRole })
        .eq('id', userId);

      if (profileErr) throw profileErr;

      // 2. Map and update user_roles and roles
      const roleNameMap: Record<string, string> = {
        admin: 'Admin',
        editor: 'Editor',
        author: 'Author',
        moderator: 'Moderator',
        subscriber: 'Subscriber',
        premium: 'Subscriber',
        superadmin: 'Super Admin',
        'super admin': 'Super Admin'
      };
      const mappedRoleName = roleNameMap[cleanRole] || 'Subscriber';

      const { data: roleData, error: roleFetchErr } = await heartsync.supabase
        .from('roles')
        .select('id')
        .eq('name', mappedRoleName)
        .maybeSingle();

      if (roleFetchErr || !roleData) {
        throw new Error(`Target role "${mappedRoleName}" is not registered in public.roles schema.`);
      }

      // Delete existing roles for this user and insert the new one
      await heartsync.supabase
        .from('user_roles')
        .delete()
        .eq('user_id', userId);

      const { error: insertRoleErr } = await heartsync.supabase
        .from('user_roles')
        .insert({
          user_id: userId,
          role_id: roleData.id,
          assigned_by: heartsync.current_user?.id || null,
          assigned_at: new Date().toISOString()
        });

      if (insertRoleErr) throw insertRoleErr;

      // 3. Keep public.admin_users synced for backward compatibility in other parts of the app
      if (['admin', 'super admin'].includes(mappedRoleName.toLowerCase())) {
        await heartsync.supabase
          .from('admin_users')
          .upsert({
            id: userId,
            email: cleanEmail,
            role: cleanRole,
            is_active: true,
            created_at: new Date().toISOString()
          });
      } else {
        await heartsync.supabase
          .from('admin_users')
          .delete()
          .eq('email', cleanEmail);
      }

      triggerToast(`Role upgraded successfully to ${mappedRoleName} for ${cleanEmail}!`);
      fetchDbUsers();
    } catch (err: any) {
      console.error('Error updating user role:', err);
      triggerToast(`Failed to update user role: ${err.message}`);
    }
  };

  const handleToggleUserSuspension = async (userId: string, userEmail: string, currentSuspended: boolean) => {
    if (!heartsync.supabase) return;
    try {
      const cleanEmail = userEmail.toLowerCase().trim();
      const newSuspended = !currentSuspended;
      const newStatus = newSuspended ? 'suspended' : 'active';

      // 1. Update profiles (syncing both is_suspended and status)
      const { error: profileErr } = await heartsync.supabase
        .from('profiles')
        .update({ 
          is_suspended: newSuspended,
          status: newStatus 
        })
        .eq('id', userId);

      if (profileErr) throw profileErr;

      // 2. Also deactivate in admin_users if they are admin
      if (newSuspended) {
        await heartsync.supabase
          .from('admin_users')
          .update({ is_active: false })
          .eq('email', cleanEmail);
      } else {
        // Restore active if they are admin
        const { data: adminUser } = await heartsync.supabase
          .from('admin_users')
          .select('*')
          .eq('email', cleanEmail)
          .maybeSingle();
        if (adminUser) {
          await heartsync.supabase
            .from('admin_users')
            .update({ is_active: true })
            .eq('email', cleanEmail);
        }
      }

      triggerToast(`User ${cleanEmail} is now ${newSuspended ? 'suspended' : 'active'}!`);
      fetchDbUsers();
    } catch (err: any) {
      console.error('Error toggling suspension:', err);
      triggerToast(`Failed to update user status: ${err.message}`);
    }
  };

