  useEffect(() => {
    const hasChanges = JSON.stringify(siteSettings) !== JSON.stringify(heartsync.site_settings);
    if (hasChanges) {
      // Debounce the setting store update to bundle typing keystrokes and prevent high network traffic saves
      const debounceTimer = setTimeout(() => {
        heartsync.updateSettings(siteSettings);
      }, 500);
      return () => clearTimeout(debounceTimer);
    }
  }, [siteSettings]);

