  // Author and Pages Form State Handlers
  const handleAuthorSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!authName.trim()) {
      triggerToast('Author name is required!');
      return;
    }
    const data = {
      name: authName.trim(),
      avatar_url: authAvatarUrl.trim() || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&q=80&w=150',
      bio: authBio.trim(),
      role_tag: authRoleTag.trim() || 'Contributor',
      social_links: {
        twitter: authTwitter.trim(),
        linkedin: authLinkedin.trim()
      }
    };

    if (editingAuthorId) {
      heartsync.updateAuthor(editingAuthorId, data);
      triggerToast(`Author profile for ${authName} synchronized.`);
    } else {
      heartsync.addAuthor(data);
      triggerToast(`Author ${authName} created successfully.`);
    }

    // Sync with current logged in user if they are the author being edited/created
    const idToCompare = editingAuthorId;
    const isCurrentUser = heartsync.current_user && (
      heartsync.current_user.id === idToCompare ||
      heartsync.current_user.name.toLowerCase() === data.name.toLowerCase()
    );

    if (isCurrentUser && heartsync.current_user) {
      heartsync.current_user = {
        ...heartsync.current_user,
        name: data.name,
        avatar_url: data.avatar_url,
        bio: data.bio
      };
      heartsync.saveState();
    }

    // Dynamic synchronization with local staffUsers state and localStore list
    setStaffUsers(prev => {
      const updated = prev.map(u => {
        const isMatch = u.id === idToCompare || u.name.toLowerCase() === data.name.toLowerCase();
        if (isMatch) {
          return {
            ...u,
            name: data.name,
            avatar: data.avatar_url,
            bio: data.bio,
            role: data.role_tag as any
          };
        }
        return u;
      });
      heartsync.setLocalStorage('pn_staff_users', JSON.stringify(updated));
      return updated;
    });

    setAuthName('');
    setAuthAvatarUrl('');
    setAuthBio('');
    setAuthRoleTag('Contributor');
    setAuthTwitter('');
    setAuthLinkedin('');
    setEditingAuthorId(null);
  };

