    setAuthAvatarUrl(author.avatar_url);
    setAuthBio(author.bio);
    setAuthRoleTag(author.role_tag || 'Contributor');
    setAuthTwitter(author.social_links?.twitter || '');
    setAuthLinkedin(author.social_links?.linkedin || '');
    setEditingAuthorId(author.id);
