  // NEW: Dynamic Administrator & Author Staff Account handlers
  const handleStaffFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newStaffName.trim() || !newStaffEmail.trim()) {
      triggerToast('Staff name and email are required!');
      return;
    }
    const staffData = {
      id: editingStaffId || 'staff-' + Date.now(),
      name: newStaffName.trim(),
      email: newStaffEmail.trim(),
      role: newStaffRole,
      bio: newStaffBio.trim(),
      avatar: newStaffAvatar.trim() || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&q=80&w=150',
      status: newStaffStatus
    };

    if (editingStaffId) {
      setStaffUsers(staffUsers.map(u => u.id === editingStaffId ? staffData : u));
      triggerToast(`Staff profile for ${newStaffName} updated!`);
    } else {
      setStaffUsers([...staffUsers, staffData]);
      triggerToast(`Newly added staff account: ${newStaffName}!`);
    }

    // Sync with current logged in user if they are the staff member being modified/defined
    const isCurrentUser = heartsync.current_user && (
      heartsync.current_user.email.toLowerCase() === staffData.email.toLowerCase() ||
      heartsync.current_user.name.toLowerCase() === staffData.name.toLowerCase()
    );

    if (isCurrentUser && heartsync.current_user) {
      heartsync.current_user = {
        ...heartsync.current_user,
        name: staffData.name,
        email: staffData.email,
        avatar_url: staffData.avatar,
        bio: staffData.bio
      };
      heartsync.saveState();
    }

    // Always synchronize to authors list to maintain consistent author profile information everywhere
    const authorIdToFind = staffData.id;
    const existingAuthor = authors.find(a => 
      a.id === authorIdToFind || 
      a.name.toLowerCase() === staffData.name.toLowerCase()
    );

    if (existingAuthor) {
      heartsync.updateAuthor(existingAuthor.id, {
        name: staffData.name,
        avatar_url: staffData.avatar,
        bio: staffData.bio,
        role_tag: String(staffData.role)
      });
    } else {
      heartsync.addAuthor({
        id: authorIdToFind,
        name: staffData.name,
        avatar_url: staffData.avatar,
        bio: staffData.bio,
        role_tag: String(staffData.role),
        social_links: { twitter: '', linkedin: '' }
      });
    }

    // Reset form
    setEditingStaffId(null);
    setNewStaffName('');
    setNewStaffEmail('');
    setNewStaffBio('');
    setNewStaffAvatar('');
    setNewStaffRole('Administrator');
    setNewStaffStatus('Active');
  };

