  // Real Google indexing & search engine submission engine
  const triggerSingleUrlIndex = async (index: number) => {
    const item = indexingUrls[index];
    if (!item) return;
    setIsIndexingIndex(index);
    try {
      const res = await fetch('/api/seo/index-submit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url: item.url })
      });
      const data = await res.json();
      if (data.success && data.results && data.results[0]) {
        const resItem = data.results[0];
        setIndexingUrls(prev => prev.map((it, i) => i === index ? {
          ...it,
          status: resItem.status,
          lastChecked: resItem.lastChecked
        } : it));
        triggerToast(`Real-time Indexing Submission: ${resItem.url} (${resItem.status}) - ${resItem.googlePingStatus}`);
      } else {
        setIndexingUrls(prev => prev.map((it, i) => i === index ? {
          ...it, status: 'Failed', lastChecked: new Date().toISOString().replace('T', ' ').substring(0, 16)
        } : it));
        triggerToast(`Failed to submit ${item.url} for Google indexing.`);
      }
    } catch (err: any) {
      setIndexingUrls(prev => prev.map((it, i) => i === index ? {
        ...it, status: 'Failed', lastChecked: new Date().toISOString().replace('T', ' ').substring(0, 16)
      } : it));
      triggerToast(`Indexing request error: ${err.message || 'Server offline'}`);
    } finally {
      setIsIndexingIndex(null);
    }
  };

  const triggerAllUrlsIndex = async () => {
    setIsIndexingAll(true);
    try {
      const urlsToSubmit = indexingUrls.map(u => u.url);
      const res = await fetch('/api/seo/index-submit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ urls: urlsToSubmit })
      });
      const data = await res.json();
      if (data.success && data.results) {
        const resultMap = new Map(data.results.map((r: any) => [r.url, r]));
        setIndexingUrls(prev => prev.map(item => {
          const match: any = resultMap.get(item.url);
          if (match) {
            return { ...item, status: match.status, lastChecked: match.lastChecked };
          }
          return item;
        }));
        triggerToast(`Successfully submitted ${data.submittedCount} routes directly to Google & Search Indexes!`);
      } else {
        triggerToast('Failed to complete bulk Google indexing request.');
      }
    } catch (err: any) {
      triggerToast(`Bulk indexing error: ${err.message || 'Server error'}`);
    } finally {
      setIsIndexingAll(false);
    }
  };

