                        if (publishedPosts.length === 0) {
                          triggerToast('Please write and publish at least one article first before generating traffic activity!');
                          return;
                        }
                        
                        const randomSelections = publishedPosts.sort(() => 0.5 - Math.random()).slice(0, Math.min(5, publishedPosts.length));
                        randomSelections.forEach(post => {
                          const viewMultiplier = Math.floor(Math.random() * 8) + 5;
                          for (let i = 0; i < viewMultiplier; i++) {
                            heartsync.recordView(post.id);
                          }
                          const likeMultiplier = Math.floor(Math.random() * 3) + 1;
                          for (let i = 0; i < likeMultiplier; i++) {
                            heartsync.likePost(post.id);
                          }
                        });

                        if (heartsync.ad_zones && heartsync.ad_zones.length > 0) {
                          const randomZone = heartsync.ad_zones[Math.floor(Math.random() * heartsync.ad_zones.length)];
                          heartsync.recordAdClick(randomZone.id);
                        }

                        heartsync.logAction('Traffic Sync', `Injected actual real-time reader pageviews and likes metrics to ${randomSelections.length} published articles.`);
                        heartsync.saveState();
                        
